(async () => {
  const feed = new DOMParser().parseFromString(await (await fetch('/feed.xml')).text(), 'application/xml');
  const path = (u) => new URL(u, location.origin).pathname;
  const links = [...document.querySelectorAll('.ptl-title a')].map((a) => path(a.href));
  const listed = new Set(links);
  if (listed.size !== links.length) throw new Error((links.length - listed.size) + ' post(s) listed twice');
  const inFeed = [...feed.querySelectorAll('entry > link[rel="alternate"]')].map((l) => path(l.getAttribute('href')));
  const missing = inFeed.filter((u) => !listed.has(u));
  if (missing.length) throw new Error(missing.length + ' feed post(s) missing from the timeline: ' + missing.join(', '));
  return { timeline: listed.size, feed: inFeed.length };
})()

(() => {
  const shown = () => [...document.querySelectorAll('.ptl-item:not([hidden])')];
  const set = (id, v, ev) => { const el = document.getElementById(id); el.value = v; el.dispatchEvent(new Event(ev)); };
  const cat = document.querySelector('#ptl-category option:nth-child(2)').value;
  set('ptl-category', cat, 'change');
  const byCat = shown();
  const wrongCat = byCat.filter((li) => !('|' + li.dataset.cats + '|').includes('|' + cat + '|'));
  set('ptl-category', '', 'change');
  set('ptl-search', 'jekyll', 'input');
  const byWord = shown();
  const wrongWord = byWord.filter((li) => !li.dataset.search.includes('jekyll'));
  set('ptl-search', '', 'input');
  if (wrongCat.length || wrongWord.length) throw new Error('filter showed ' + (wrongCat.length + wrongWord.length) + ' post(s) it should have hidden');
  return { category: cat, byCategory: byCat.length, byWord: byWord.length, total: shown().length, count: document.getElementById('ptl-count').textContent };
})()

(async () => {
  const bar = document.querySelectorAll('#ptl-cadence rect.ptl-col')[2];
  const month = bar.querySelector('title').textContent.slice(0, 7);
  bar.dispatchEvent(new MouseEvent('click', { bubbles: true }));
  await new Promise((r) => setTimeout(r, 900));
  // the month must be on screen; near the end of the page it cannot scroll to the top
  const r = document.getElementById('posts-' + month).getBoundingClientRect();
  if (r.top < 0 || r.top > innerHeight - 40) throw new Error('month ' + month + ' is at ' + Math.round(r.top) + 'px, off screen after the jump');
  return { month, top: Math.round(r.top), viewport: innerHeight };
})()

